<?php
namespace App\Http\Controllers;use App\Services\StudentGamificationService;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class LearningQuizController extends Controller {public function store(Request $r,StudentGamificationService $service):JsonResponse{$data=$r->validate(['track'=>'required|string|max:80','module'=>'required|string|max:100','lesson'=>'required|integer|min:1|max:500','selected_option'=>'required|integer|min:0|max:3']);abort_unless(($r->user()->role_code===1||$r->user()->role==='student'),403);$topic=config("learning_tracks.{$data['track']}.topics.{$data['module']}");abort_unless($topic&&($topic['type']??null)==='tutorial',404);$config=$topic['lessons_config']??null;$lessons=$config?array_slice(config($config,[]),$topic['offset']??0,$topic['limit']??null):array_merge(config('laravel_foundations',[]),config('laravel_advanced',[]));$lesson=$lessons[$data['lesson']-1]??null;abort_unless($lesson,404);$key=hash('sha256',implode('|',[$data['track'],$data['module'],$data['lesson']]));$existing=DB::table('learning_quiz_answers')->where('user_id',$r->user()->id)->where('question_key',$key)->first();if($existing)return response()->json(['correct'=>(bool)$existing->is_correct,'already_answered'=>true,'points'=>$r->user()->total_points,'stars'=>$r->user()->total_stars,'premium'=>(bool)$r->user()->is_premium]);$correct=(int)$lesson['answer']===$data['selected_option'];DB::table('learning_quiz_answers')->insert(['user_id'=>$r->user()->id,'question_key'=>$key,'track'=>$data['track'],'module'=>$data['module'],'lesson_number'=>$data['lesson'],'selected_option'=>$data['selected_option'],'is_correct'=>$correct,'points_earned'=>$correct?1:0,'created_at'=>now(),'updated_at'=>now()]);$stats=$correct?$service->award($r->user()):['points'=>$r->user()->total_points,'stars'=>$r->user()->total_stars,'premium'=>(bool)$r->user()->is_premium,'premium_activated'=>false];return response()->json(['correct'=>$correct,'already_answered'=>false]+$stats);}}
